-- Ensemble predictions (AI Football Analyst Phase 1) — the combined-model
-- output for the accumulator engine, generated by
-- backend/src/jobs/generateEnsemblePredictions.ts from ml-service's
-- POST /predict/ensemble. Deliberately a new table rather than reusing
-- predictions: that table's risk_classification column is constrained to
-- ('low', 'moderate', 'high') and is already load-bearing for the existing
-- Poisson/gradient-boosting output, whereas this engine needs a different,
-- 5-tier scheme (elite/strong/medium/high_risk/avoid) — same reasoning
-- 0008_competition_rho.sql gives for not folding rho fits into
-- league_calibration despite the superficial similarity.
--
-- Same versioning pattern as predictions (generated_at/superseded_at,
-- never overwritten in place) — this is also what makes the table usable
-- as prediction history: "what was the live prediction immediately before
-- kickoff" is answerable via
-- generated_at <= fixtures.kickoff_utc and
-- (superseded_at is null or superseded_at > fixtures.kickoff_utc)
-- without needing any future migration. Settling these against actual
-- results and computing P&L is Phase 2 — not built yet, but this shape
-- doesn't need to change to support it.
--
-- component_probabilities/component_weights_used/missing_components record
-- exactly which of the six ensemble components (elo, poisson, form,
-- home_away, injuries, market) were actually available and what weight
-- each got after redistribution — so a selection score can always be
-- explained/audited without guessing.
create table ensemble_predictions (
  id uuid primary key default gen_random_uuid(),
  fixture_id uuid not null references fixtures(id) on delete cascade,
  ensemble_version_id uuid not null references model_versions(id),
  market text not null default '1x2',
  selection text not null, -- 'home', 'draw', 'away'
  combined_probability numeric not null check (combined_probability >= 0 and combined_probability <= 1),
  component_probabilities jsonb not null default '{}'::jsonb,
  component_weights_used jsonb not null default '{}'::jsonb,
  missing_components text[] not null default '{}',
  consensus_level text not null check (consensus_level in ('high', 'moderate', 'low', 'conflicting')),
  selection_score numeric not null check (selection_score >= 0 and selection_score <= 100),
  risk_tier text not null check (risk_tier in ('elite', 'strong', 'medium', 'high_risk', 'avoid')),
  ev numeric,
  edge_pct numeric,
  best_odds numeric,
  best_bookmaker text,
  data_quality text not null check (data_quality in ('insufficient', 'limited', 'strong')),
  factors jsonb not null default '[]'::jsonb,
  generated_at timestamptz not null default now(),
  superseded_at timestamptz,
  created_at timestamptz not null default now()
);

create index idx_ensemble_predictions_fixture on ensemble_predictions (fixture_id, market);
create index idx_ensemble_predictions_current on ensemble_predictions (fixture_id) where superseded_at is null;
create index idx_ensemble_predictions_score on ensemble_predictions (selection_score desc) where superseded_at is null;
